# Select representative lots across T (low, median, high observed y within each T)
sel_lots = []
for T, df in exp_results.items():
    d = df.sort_values("y").reset_index(drop=True)
    picks = [d.loc[0, "lot_id"], d.loc[len(d)//2, "lot_id"], d.loc[len(d)-1, "lot_id"]]
    # keep unique while preserving order
    for lot in picks:
        if lot not in sel_lots and len(sel_lots) < 6:
            sel_lots.append(lot)
print("Selected lots for deep check:", sel_lots)

remeas = {}
for lot in sel_lots:
    remeas[lot] = {
        "same": env.measure(lot, reps=5),
        "revial": env.measure(f"revial:{lot}", reps=5),
    }
    print(f"\nLOT {lot} same-vial summary")
    print(remeas[lot]["same"]["y"].describe())
    print(f"LOT {lot} revial summary")
    print(remeas[lot]["revial"]["y"].describe())

receipt = env.lab_extern(sel_lots)
print("\nExternal lab receipt:", receipt)
